<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createCourse, createLesson, deleteCourse, deleteLesson, getAdminCourse, getAdminCourses, updateCourse, updateCourseStatus, updateLesson, type Course, type CourseLesson } from '@/api/courses'
import { useRoute } from 'vue-router'
const records = ref<Course[]>([]); const loading = ref(true); const dialog = ref(false); const lessonDialog = ref(false); const editing = ref(false); const current = ref<Course | null>(null); const saving = ref(false); const route = useRoute(); const form = reactive({ title:'', coverUrl:'', danceType:'Hip-hop', difficulty:'BEGINNER', teacherName:'', description:'', sortNo:0 }); const lessonForm = reactive({ id: 0, title:'', videoUrl:'', duration:0, content:'', sortNo:1, status:'PUBLISHED' })
const labels: Record<string, string> = { DRAFT: '草稿', PUBLISHED: '已上架', OFFLINE: '已下架' }
async function load() { loading.value = true; try { const all = (await getAdminCourses({ page: 1, pageSize: 100 })).data.records; const keyword = String(route.query.keyword || '').toLowerCase(); records.value = all.filter(item => (!keyword || `${item.title} ${item.teacherName}`.toLowerCase().includes(keyword)) && (!route.query.danceType || item.danceType === route.query.danceType) && (!route.query.status || item.status === route.query.status)) } finally { loading.value = false } }
onMounted(load)
watch(() => route.fullPath, load)
function openCreate() { editing.value = false; Object.assign(form, { title:'', coverUrl:'', danceType:'Hip-hop', difficulty:'BEGINNER', teacherName:'', description:'', sortNo:0 }); dialog.value = true }
async function openEdit(row: Course) { editing.value = true; current.value = row; Object.assign(form, (await getAdminCourse(String(row.id))).data); dialog.value = true }
async function saveCourse() { if (!form.title.trim() || !form.teacherName.trim()) { ElMessage.error('请填写课程标题和教师姓名'); return }; saving.value = true; try { editing.value ? await updateCourse(String(current.value!.id), form) : await createCourse(form); dialog.value = false; ElMessage.success('课程已保存'); await load() } finally { saving.value = false } }
async function status(row: Course) { const next = row.status === 'PUBLISHED' ? 'OFFLINE' : 'PUBLISHED'; await updateCourseStatus(row.id, next); ElMessage.success('课程状态已更新'); await load() }
async function remove(row: Course) { try { await ElMessageBox.confirm('课程删除前必须先删除全部课时，确定继续吗？', '删除课程'); await deleteCourse(row.id); ElMessage.success('课程已删除'); await load() } catch { /* cancel or business error */ } }
async function openLesson(row: Course, lesson?: CourseLesson) { current.value = (await getAdminCourse(String(row.id))).data; Object.assign(lessonForm, lesson ? { ...lesson, id: Number(lesson.id) } : { id:0, title:'', videoUrl:'', duration:0, content:'', sortNo:(current.value.lessons?.length || 0) + 1, status:'PUBLISHED' }); lessonDialog.value = true }
async function saveLesson() { if (!lessonForm.title.trim()) { ElMessage.error('请填写课时标题'); return }; saving.value = true; try { const payload = { title: lessonForm.title, videoUrl: lessonForm.videoUrl, duration: lessonForm.duration, content: lessonForm.content, sortNo: lessonForm.sortNo, status: lessonForm.status }; lessonForm.id ? await updateLesson(lessonForm.id, payload) : await createLesson(current.value!.id, payload); lessonDialog.value = false; ElMessage.success('课时已保存'); await load() } finally { saving.value = false } }
async function removeLesson(lesson: CourseLesson) { await ElMessageBox.confirm(`确定删除「${lesson.title}」吗？`, '删除课时'); await deleteLesson(lesson.id); ElMessage.success('课时已删除'); await load() }
</script>
<template><section class="content"><div class="title"><div><h1>课程管理</h1><p>维护课程、课时内容和上架状态。</p></div><el-button type="primary" @click="openCreate">新增课程</el-button></div><el-table v-loading="loading" :data="records" row-key="id"><el-table-column prop="title" label="课程名称" min-width="220" /><el-table-column prop="danceType" label="舞种" /><el-table-column prop="teacherName" label="教师" /><el-table-column label="课时"><template #default="scope">{{ scope.row.lessonCount || 0 }}</template></el-table-column><el-table-column label="状态"><template #default="scope"><el-tag>{{ labels[scope.row.status] || scope.row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="360"><template #default="scope"><el-button link @click="openEdit(scope.row)">编辑</el-button><el-button link @click="openLesson(scope.row)">新增课时</el-button><el-button link type="primary" @click="status(scope.row)">{{ scope.row.status === 'PUBLISHED' ? '下架' : '上架' }}</el-button><el-button link type="danger" @click="remove(scope.row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading && !records.length" description="暂无课程" /><el-dialog v-model="dialog" :title="editing ? '编辑课程' : '新增课程'" width="560px"><el-form label-position="top"><el-form-item label="课程标题" required><el-input v-model="form.title" /></el-form-item><div class="two-col"><el-form-item label="舞种"><el-input v-model="form.danceType" /></el-form-item><el-form-item label="难度"><el-select v-model="form.difficulty" style="width:100%"><el-option label="入门" value="BEGINNER" /><el-option label="进阶" value="INTERMEDIATE" /><el-option label="高级" value="ADVANCED" /></el-select></el-form-item></div><el-form-item label="教师姓名" required><el-input v-model="form.teacherName" /></el-form-item><el-form-item label="课程描述"><el-input v-model="form.description" type="textarea" :rows="4" /></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortNo" :min="0" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCourse">保存</el-button></template></el-dialog><el-dialog v-model="lessonDialog" title="课时管理" width="560px"><el-form label-position="top"><el-form-item label="课时标题" required><el-input v-model="lessonForm.title" /></el-form-item><div class="two-col"><el-form-item label="时长（秒）"><el-input-number v-model="lessonForm.duration" :min="0" /></el-form-item><el-form-item label="排序"><el-input-number v-model="lessonForm.sortNo" :min="1" /></el-form-item></div><el-form-item label="视频地址"><el-input v-model="lessonForm.videoUrl" /></el-form-item><el-form-item label="内容"><el-input v-model="lessonForm.content" type="textarea" :rows="4" /></el-form-item></el-form><div v-if="current?.lessons?.length" class="existing-lessons"><p>已有课时</p><div v-for="lesson in current.lessons" :key="lesson.id"><span>{{ lesson.sortNo }}. {{ lesson.title }}</span><span><el-button link @click="openLesson(current!, lesson)">编辑</el-button><el-button link type="danger" @click="removeLesson(lesson)">删除</el-button></span></div></div><template #footer><el-button @click="lessonDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveLesson">保存课时</el-button></template></el-dialog></section></template>
<style scoped>.content { padding: 0; }.title { display:flex; justify-content:space-between; align-items:start; margin-bottom:20px; }.title h1 { margin:0; color:var(--df-primary-950); }.title p { margin:8px 0 0; color:#77717e; }.two-col { display:grid; grid-template-columns:1fr 1fr; gap:18px; }.existing-lessons { margin-top:12px; border-top:1px solid #eee8f1; }.existing-lessons p { color:#77717e; font-size:13px; }.existing-lessons div { display:flex; justify-content:space-between; padding:8px 0; border-bottom:1px solid #f1edf3; font-size:13px; }@media (max-width:600px) { .two-col { grid-template-columns:1fr; gap:0; } }</style>
